INSERT INTO "documents" VALUES('practice_tasks','practice-b65fdf71-e094-47b9-a988-84b22fbf19bc:0','{"id": "practice-b65fdf71-e094-47b9-a988-84b22fbf19bc:0", "concept_id": "paths", "question": "Two paths have amplitudes $1/2$ and $e^{i\\phi}/2$. Find $P(\\phi)$ and when it is zero.", "origin": "self_created", "source_refs": [], "status": "attempted", "history": [{"action": "hint", "feedback": "Expand $|z|^2 = z^* z$ first."}, {"action": "assess", "feedback": "$P(\\phi)$ is right; check when the cosine is $-1$.", "outcome": "needs_work", "evidence_id": "practice-evidence:practice-3fdaffd6-293e-4f4e-8113-bd5559607280", "kind": "needs_work", "answer": "P = (1 + cos phi)/2, zero at phi = 0."}, {"action": "assess", "feedback": "Right: $P = (1 + \\cos\\phi)/2$, zero at $\\phi = \\pi$.", "outcome": "passed", "evidence_id": "practice-evidence:practice-e5b19c48-a5ce-4f27-bbd9-759973398692", "kind": "hinted", "answer": "P = (1 + cos phi)/2, zero at phi = pi."}]}');
